mapper.delete:

delete from public.sequencias_contrato
where organizacao_id = #{organizacaoId,jdbcType=OTHER}
  and ano = #{ano,jdbcType=INTEGER}

mapper.update:

update public.sequencias_contrato
set ultimo_numero = #{ultimoNumero,jdbcType=BIGINT},
  atualizado_em = #{atualizadoEm,jdbcType=TIMESTAMP_WITH_TIMEZONE}
where organizacao_id = #{organizacaoId,jdbcType=OTHER}
  and ano = #{ano,jdbcType=INTEGER}

mapper.select:

select organizacao_id, ano, ultimo_numero, atualizado_em
from public.sequencias_contrato
where organizacao_id = #{organizacaoId,jdbcType=OTHER}
  and ano = #{ano,jdbcType=INTEGER}
